(() => {
 'use strict';
 const data=window.BINGO_DATA,labels={personal:'Личная атака',diversion:'Подмена темы',pressure:'Давление нормой',context:'Контекст важен'};
 const escape=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 const grid=document.getElementById('grid'),dialog=document.getElementById('detail');let active=0,opener=null;
 grid.innerHTML=data.map((item,index)=>`<button type="button" class="cell ${item.category}" data-index="${index}" aria-haspopup="dialog" aria-label="Клетка ${index+1}. ${escape(item.title)}. Открыть разбор"><span class="cell-top"><span class="cell-category">${labels[item.category]}</span><span class="cell-number">${String(index+1).padStart(2,'0')}</span></span><span class="cell-title">${escape(item.title)}</span><span class="cell-sub">${escape(item.sub)}</span><span class="cell-arrow" aria-hidden="true">↗</span></button>`).join('');
 function render(index){active=index;const item=data[index];document.getElementById('detail-coordinate').textContent=`TP BINGO / КЛЕТКА ${String(index+1).padStart(2,'0')} / v3.01`;document.getElementById('detail-count').textContent=`${index+1} из ${data.length}`;document.getElementById('prev').disabled=index===0;document.getElementById('next').disabled=index===data.length-1;
 document.getElementById('detail-body').innerHTML=`<header class="detail-hero ${item.category}"><span class="label">${escape(item.type)}</span><h2 id="detail-title" tabindex="-1">${escape(item.title)}</h2><p class="original"><strong>В исходной клетке:</strong> ${escape(item.original)}</p></header><div class="detail-layout"><article class="analysis"><section><h3>Что происходит в разговоре</h3>${item.analysis.map(p=>`<p>${escape(p)}</p>`).join('')}</section><section><h3>Как распознать подмену</h3><p>${escape(item.test)}</p></section><section><h3>Примеры</h3><p>Скоро добавим примеры</p></section><section class="not-always"><h3>Когда это не манипуляция</h3><p>${escape(item.context)}</p></section><section class="graham-card"><h3>Место в пирамиде Грэма</h3><p>${escape(item.graham)}</p><a href="https://www.paulgraham.com/disagree.html" target="_blank" rel="noopener noreferrer">Шкала Грэма [2] ↗</a></section></article><aside class="detail-aside"><h3>Можно ответить так</h3><blockquote class="reply">«${escape(item.reply)}»</blockquote><h3>Как защитить свои границы</h3><ol class="protect">${item.protect.map(s=>`<li>${escape(s)}</li>`).join('')}</ol><div class="pitfall"><h3>Ловушка ответной реакции</h3><p>${escape(item.pitfall)}</p></div></aside></div>`;dialog.scrollTop=0;}
 grid.addEventListener('click',e=>{const cell=e.target.closest('[data-index]');if(!cell)return;opener=cell;render(Number(cell.dataset.index));dialog.showModal();document.body.classList.add('modal-open');document.getElementById('detail-title').focus({preventScroll:true});});
 dialog.querySelector('.close-button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus({preventScroll:true});});
 document.getElementById('prev').addEventListener('click',()=>{if(active>0){render(active-1);document.getElementById('detail-title').focus({preventScroll:true});}});document.getElementById('next').addEventListener('click',()=>{if(active<data.length-1){render(active+1);document.getElementById('detail-title').focus({preventScroll:true});}});
})();
